BEGIN TRANSACTION;
CREATE TABLE cart (cart_id INTEGER PRIMARY KEY AUTOINCREMENT, customer_id integer NOT NULL, product_id integer NOT NULL, quantity integer NOT NULL, created_data text NOT NULL, FOREIGN KEY (customer_id) REFERENCES customers(customer_id), FOREIGN KEY (product_id) REFERENCES products(product_id));
CREATE TABLE category (category_id INTEGER PRIMARY KEY AUTOINCREMENT, category_name TEXT NOT NULL, created_data text NOT NULL);
CREATE TABLE colors (color_id INTEGER PRIMARY KEY AUTOINCREMENT, color_name TEXT NOT NULL, created_data text NOT NULL);
CREATE TABLE customers (customer_id INTEGER PRIMARY KEY AUTOINCREMENT, customer_name TEXT NOT NULL, customer_email TEXT NOT NULL, customer_password TEXT NOT NULL, created_data text NOT NULL);
CREATE TABLE orders (order_id INTEGER PRIMARY KEY AUTOINCREMENT, customer_id integer NOT NULL, product_id integer NOT NULL, quantity integer NOT NULL, order_status TEXT NOT NULL, created_data text NOT NULL, FOREIGN KEY (customer_id) REFERENCES customers(customer_id), FOREIGN KEY (product_id) REFERENCES products(product_id));
CREATE TABLE products (product_id INTEGER PRIMARY KEY AUTOINCREMENT, product_name TEXT NOT NULL, product_price integer NOT NULL, product_description TEXT NOT NULL, subcategory_id integer NOT NULL, color_id integer NOT NULL, size_id integer NOT NULL, created_data text NOT NULL, FOREIGN KEY (subcategory_id) REFERENCES subcategory(subcategory_id), FOREIGN KEY (color_id) REFERENCES colors(color_id), FOREIGN KEY (size_id) REFERENCES size(size_id));
CREATE TABLE size (size_id INTEGER PRIMARY KEY AUTOINCREMENT, size_name TEXT NOT NULL, created_data text NOT NULL);
CREATE TABLE subcategory (subcategory_id INTEGER PRIMARY KEY AUTOINCREMENT, subcategory_name TEXT NOT NULL, category_id integer NOT NULL, created_data text NOT NULL, FOREIGN KEY (category_id) REFERENCES category(category_id));
COMMIT;
